ALTER TABLE public.pm_allocations ADD COLUMN IF NOT EXISTS day_part text CHECK (day_part IS NULL OR day_part IN ('full','am','pm')), ADD COLUMN IF NOT EXISTS is_site_visit boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS public.pm_week_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), week_start date NOT NULL UNIQUE CHECK (extract(isodow from week_start)=1), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')), created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), approved_by uuid, approved_at timestamptz);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pm_week_plans TO authenticated; GRANT ALL ON public.pm_week_plans TO service_role;
ALTER TABLE public.pm_week_plans ENABLE ROW LEVEL SECURITY;
DO $policy$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='pm_week_plans' AND policyname='week_plans_planners') THEN CREATE POLICY week_plans_planners ON public.pm_week_plans FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_module_permission(auth.uid(),'projects.edit_planning','all')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_module_permission(auth.uid(),'projects.edit_planning','all')); END IF; END $policy$;
CREATE TABLE IF NOT EXISTS public.pm_week_plan_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES public.pm_week_plans(id) ON DELETE CASCADE, resource_id uuid NOT NULL REFERENCES public.pm_resources(id) ON DELETE CASCADE, day date NOT NULL, part text NOT NULL CHECK(part IN ('am','pm')), project_id uuid NOT NULL REFERENCES public.pm_projects(id) ON DELETE CASCADE, stage_id uuid REFERENCES public.pm_stages(id) ON DELETE SET NULL, is_site_visit boolean NOT NULL DEFAULT false, UNIQUE(plan_id,resource_id,day,part));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pm_week_plan_slots TO authenticated; GRANT ALL ON public.pm_week_plan_slots TO service_role;
ALTER TABLE public.pm_week_plan_slots ENABLE ROW LEVEL SECURITY;
DO $policy$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='pm_week_plan_slots' AND policyname='week_slots_planners') THEN CREATE POLICY week_slots_planners ON public.pm_week_plan_slots FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_module_permission(auth.uid(),'projects.edit_planning','all')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_module_permission(auth.uid(),'projects.edit_planning','all')); END IF; END $policy$;
CREATE OR REPLACE FUNCTION public.pm_week_board(_week_start date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $fn$
DECLARE result jsonb; planner boolean;
BEGIN
 IF auth.uid() IS NULL OR NOT public.is_psa_staff() THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 IF _week_start IS NULL OR extract(isodow from _week_start)<>1 THEN RAISE EXCEPTION 'Week must start on Monday'; END IF;
 planner := public.has_role(auth.uid(),'admin') OR public.has_module_permission(auth.uid(),'projects.edit_planning','all');
 WITH resources AS (SELECT r.id,r.name,r.color,r.collaborator_id,r.weekly_capacity FROM public.pm_resources r WHERE r.active=true),
 projects AS (SELECT p.id,p.name,p.client,p.color FROM public.pm_projects p WHERE p.status='active'),
 stages AS (SELECT s.id,s.project_id,s.name,s.start_date,s.end_date,s.sort_order,s.parent_stage_id,s.stage_kind,s.is_milestone,s.is_self FROM public.pm_stages s JOIN projects p ON p.id=s.project_id WHERE NOT coalesce(s.is_milestone,false) AND coalesce(s.stage_kind,'')<>'retainer_monthly' AND s.archived_at IS NULL AND coalesce(s.status::text,'planned')<>'cancelled' AND NOT EXISTS(SELECT 1 FROM public.pm_stages child WHERE child.parent_stage_id=s.id AND child.archived_at IS NULL AND coalesce(child.status::text,'planned')<>'cancelled')),
 allocations AS (SELECT a.id,a.resource_id,a.stage_id,s.project_id,a.start_date,a.end_date,a.hours_per_day,a.day_part,a.is_site_visit,a.status,a.is_locked,a.source FROM public.pm_allocations a JOIN stages s ON s.id=a.stage_id JOIN resources r ON r.id=a.resource_id WHERE a.start_date<=_week_start+6 AND a.end_date>=_week_start),
 days AS (SELECT _week_start+i AS day FROM generate_series(0,4) i),
 leave_days AS (SELECT DISTINCT r.id AS resource_id,d.day,'leave'::text AS kind,NULL::text AS name FROM resources r JOIN public.vacation_requests v ON v.collaborator_id=r.collaborator_id JOIN days d ON d.day BETWEEN v.data_inicio AND v.data_fim WHERE v.estado IN ('aprovada','aprovado') UNION ALL SELECT r.id,d.day,'holiday',h.nome FROM resources r CROSS JOIN days d JOIN public.holidays h ON h.data=d.day)
 SELECT jsonb_build_object('resources',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.name) FROM resources r),'[]'::jsonb),'projects',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.name) FROM projects p),'[]'::jsonb),'stages',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.sort_order) FROM stages s),'[]'::jsonb),'allocations',coalesce((SELECT jsonb_agg(to_jsonb(a)) FROM allocations a),'[]'::jsonb),'leave',coalesce((SELECT jsonb_agg(to_jsonb(l)) FROM leave_days l),'[]'::jsonb),'plan',(SELECT jsonb_build_object('id',p.id,'status',p.status,'approved_by',p.approved_by,'approved_at',p.approved_at) FROM public.pm_week_plans p WHERE p.week_start=_week_start AND (planner OR p.status='approved')),'draft_slots',CASE WHEN planner THEN coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM public.pm_week_plan_slots s JOIN public.pm_week_plans p ON p.id=s.plan_id WHERE p.week_start=_week_start),'[]'::jsonb) ELSE '[]'::jsonb END,'my_collaborator_id',public.get_my_collaborator_id()) INTO result;
 RETURN result;
END $fn$;
REVOKE ALL ON FUNCTION public.pm_week_board(date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_week_board(date) TO authenticated;
COMMENT ON FUNCTION public.pm_week_board(date) IS 'Stage 1 staff-only weekly planning projection, no pay/cost fields. Approved leave states and weekday full-day expansion mirror non-working-sync.ts; no timesheet writes.';
